+                replayClaim,
+                "uncertain",
+                completedAtEpochMillis,
+                completion
+              )
+            );
+            return yield* atomic.transact({
+              conditions: [
+                { _tag: "Equals", key: replayClaim.key, value: expected },
+              ],
+              mutations: [
+                {
+                  _tag: "Set",
+                  key: replayClaim.key,
+                  ttl: Duration.millis(options.ttlSeconds * 1_000),
+                  value,
+                },
+              ],
+            });
+          })
+        ),
+        Match.exhaustive
+      ).pipe(
+        Effect.mapError(
+          () =>
+            new SendblueReplayStoreError({
+              message: "Unable to transition the Sendblue replay record.",
+            })
+        )
+      );
+      return yield* Match.value(outcome).pipe(
+        Match.when("applied", () => Effect.void),
+        Match.when("conflict", () =>
+          Effect.fail(
+            new SendblueReplayStoreError({
+              message: "The Sendblue replay claim is no longer active.",
+            })
+          )
+        ),
+        Match.exhaustive
+      );
+    });
+    return SendblueReplayStore.of({
+      claimInbound: (messageHandle) =>
+        deriveReplayKey(options, "inbound", [messageHandle]).pipe(
